<fieldset class="border rounded-3 p-3 sale-line"><legend class="float-none w-auto fs-6 px-2">Vật tư <span class="line-number">{{ is_numeric($i) ? $i+1 : '' }}</span></legend><div class="row g-3"><div class="col-12 col-lg-6"><label class="form-label" for="product-{{ $i }}">Vật tư *</label><select class="form-select sale-product" required data-field="product_id" id="product-{{ $i }}" name="lines[{{ $i }}][product_id]"><option value="">Chọn vật tư</option>@foreach($products as $product)<option value="{{ $product->id }}" data-price="{{ $product->sale_price }}" @selected(($line['product_id'] ?? '') === $product->id)>{{ $product->code }} · {{ $product->name }} · Tồn {{ $product->stock?->quantity ?? '0.000' }} {{ $product->unit->name }}</option>@endforeach</select></div><div class="col-6 col-lg-2"><label class="form-label" for="quantity-{{ $i }}">Số lượng *</label><input class="form-control" required inputmode="decimal" maxlength="16" data-field="quantity" id="quantity-{{ $i }}" name="lines[{{ $i }}][quantity]" value="{{ $line['quantity'] ?? '' }}"></div><div class="col-6 col-lg-3"><label class="form-label" for="price-{{ $i }}">Đơn giá (VND) *</label><input class="form-control sale-price" required inputmode="decimal" maxlength="19" data-field="unit_price" id="price-{{ $i }}" name="lines[{{ $i }}][unit_price]" value="{{ $line['unit_price'] ?? '' }}"></div><div class="col-12 col-lg-1 d-flex align-items-end"><button class="btn btn-outline-danger remove-sale-line" type="button">Bỏ</button></div></div></fieldset>
